import NextAuth from "next-auth";
import Credentials from "next-auth/providers/credentials";
import { authConfig } from "./auth.config";
import { findOrCreateOAuthUser, getUserByEmail, verifyPassword } from "@/lib/users";

export const { handlers, auth, signIn, signOut } = NextAuth({
  ...authConfig,
  session: { strategy: "jwt" },
  providers: [
    ...authConfig.providers,
    Credentials({
      credentials: {
        email: { label: "Email", type: "email" },
        password: { label: "Password", type: "password" },
      },
      authorize: async (credentials) => {
        const email = credentials?.email;
        const password = credentials?.password;
        if (typeof email !== "string" || typeof password !== "string") {
          return null;
        }

        const user = await getUserByEmail(email);
        if (!user?.passwordHash) return null;

        const valid = await verifyPassword(password, user.passwordHash);
        if (!valid) return null;

        return { id: user.id, email: user.email, name: user.name };
      },
    }),
  ],
  callbacks: {
    ...authConfig.callbacks,
    async signIn({ user, account }) {
      // New Google sign-ins need a matching row in our own user store.
      if (account?.provider === "google") {
        if (!user.email) return false;
        await findOrCreateOAuthUser({ email: user.email, name: user.name ?? user.email });
      }
      return true;
    },
    async jwt({ token, user }) {
      // Resolve to our own user id (not the OAuth provider's id) so it stays
      // consistent whether someone signed in via credentials or Google.
      if (user?.email) {
        const appUser = await getUserByEmail(user.email);
        if (appUser) token.id = appUser.id;
      }
      return token;
    },
    async session({ session, token }) {
      if (session.user && typeof token.id === "string") {
        session.user.id = token.id;
      }
      return session;
    },
  },
});

