import { auth } from "@/auth";
import { listUsers } from "@/lib/users";
import { signOutAction } from "./actions";

export default async function DashboardPage() {
  const session = await auth();
  if (!session?.user) {
    // Belt and suspenders — middleware already gates this route.
    redirect("/login");
  }

  const all = await listUsers();

  return (
    <main className="mx-auto max-w-2xl p-8">
      <div className="flex items-center justify-between">
        <h1 className="text-2xl font-semibold">Dashboard</h1>
        <form action={signOutAction}>
          <button
            type="submit"
            className="rounded-full border border-black/[.15] px-4 py-1.5 text-sm font-medium transition-colors hover:bg-black/[.04] dark:border-white/[.2] dark:hover:bg-[#1a1a1a]"
          >
            Sign out
          </button>
        </form>
      </div>
      <p className="mt-2 text-sm opacity-70">
        Signed in as {session.user.name ?? "nobody"} ({session.user.email ?? "—"})
      </p>

      <h2 className="mt-8 text-lg font-medium">Team</h2>
      <ul className="mt-2 space-y-1">
        {all.map((u) => (
          <li key={u.id} className="text-sm">
            {u.name} — {u.email} — joined {u.createdAt}
          </li>
        ))}
      </ul>
    </main>
  );
}

