const { chromium } = require("playwright-core");

const BASE = "http://localhost:3411";
const EMAIL = `test-${Date.now()}@example.com`;
const PASSWORD = "correct-horse-battery";
const NAME = "Test User";

(async () => {
  const browser = await chromium.launch({
    executablePath: "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome",
    headless: true,
  });
  const page = await browser.newPage();
  const results = {};

  // 1) /dashboard redirects to /login when signed out
  await page.goto(`${BASE}/dashboard`, { waitUntil: "networkidle" });
  results.step1_redirect_url = page.url();

  // 2) sign up
  await page.goto(`${BASE}/signup`, { waitUntil: "networkidle" });
  await page.fill('input[name="name"]', NAME);
  await page.fill('input[name="email"]', EMAIL);
  await page.fill('input[name="password"]', PASSWORD);
  await Promise.all([
    page.waitForURL(`${BASE}/dashboard`, { timeout: 10000 }).catch((e) => e),
    page.click('button[type="submit"]'),
  ]);
  results.step2_url_after_signup = page.url();
  results.step2_body = (await page.textContent("body")).replace(/\s+/g, " ").slice(0, 400);

  // 3) sign out, then sign back in
  const signOutBtn = page.locator('button:has-text("Sign out")').first();
  await signOutBtn.click();
  await page.waitForURL(`${BASE}/login`, { timeout: 10000 }).catch(() => {});
  results.step3a_url_after_signout = page.url();

  await page.goto(`${BASE}/login`, { waitUntil: "networkidle" });
  await page.fill('input[name="email"]', EMAIL);
  await page.fill('input[name="password"]', PASSWORD);
  await Promise.all([
    page.waitForURL(`${BASE}/dashboard`, { timeout: 10000 }).catch((e) => e),
    page.click('button[type="submit"]'),
  ]);
  results.step3b_url_after_login = page.url();
  results.step3b_body = (await page.textContent("body")).replace(/\s+/g, " ").slice(0, 400);

  // 4) Google button triggers OAuth redirect
  // sign out first so /login form is usable again
  await page.locator('button:has-text("Sign out")').first().click().catch(() => {});
  await page.goto(`${BASE}/login`, { waitUntil: "networkidle" });
  const [popupOrNav] = await Promise.all([
    page.waitForURL(/accounts\.google\.com/, { timeout: 10000 }).catch((e) => e),
    page.click('button:has-text("Continue with Google")'),
  ]);
  results.step4_url_after_google_click = page.url();

  console.log(JSON.stringify(results, null, 2));
  await browser.close();
})().catch((err) => {
  console.error("FAILED:", err);
  process.exit(1);
});

